fn starts_with(s: &[char], p: &[char]) -> bool {
    // Precondition: p must be a valid slice of characters
    // Ensures: Returns true if s starts with p, false otherwise
    // Requires: p.len() <= s.len() || p.is_empty()
    // Ensures: if p.is_empty() then returns true
    // Ensures: if s.len() < p.len() then returns false
    // Ensures: if s.len() >= p.len() then returns true if all characters match
    let result: bool;
    if p.is_empty() {
        result = true; // An empty prefix matches any sequence
    } else if s.len() < p.len() {
        result = false; // Sequence is shorter than the prefix
    } else {
        result = s.iter().zip(p.iter()).all(|(sc, pc)| sc == pc); // Check if all characters match
    }
    result
}

fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    // Precondition: v and p must be valid vectors of characters
    // Ensures: Returns true if v starts with p, false otherwise
    // Requires: p.len() <= v.len() || p.is_empty()
    starts_with(v, p)
}

fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    // Precondition: xs must be a valid vector of vectors of characters
    // Ensures: Returns a vector containing all sequences from xs that start with p
    // Requires: p must be a valid vector of characters
    // Ensures: for all seq in the result, has_prefix(seq, &p) is true
    let result: Vec<Vec<char>> = xs.into_iter()
        .filter(|seq| has_prefix(seq, &p))
        .collect(); // Collect the filtered sequences into a new Vec
    result
}

